const escapeHTML=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function mapPlace(id){const room=ROOMS[id],floor=schoolFloorFor(id);return {...room.map,label:(floor&&!schoolHallId(id)?floor.number+'층 · ':'')+(room.map.label??room.label)};}
function mission(progress,roomId){
 const garden=progress.garden??initialGarden();
 if(garden.phase==='ready')return gardenMessage(garden);
 if(roomId==='home'&&garden.petals>0)return `모은 꽃잎 ${garden.petals}개 · 안쪽 탁자에서 꽃 장식을 만들어요`;
 if(garden.phase==='growing')return `꽃이 자라는 중 · 서로 다른 놀이 ${garden.moments.length} / 2. 그네·책·벤치에서 잠깐 머물러요`;
 if(roomId==='park')return '꽃밭 한 곳에 물을 주면 세 꽃밭이 함께 자라요';
 if(roomId==='home')return progress.completedActivityIds.length?'내 별등이 반짝여요. 지도로 놀러 갈까요?':progress.ownedItemIds.includes('star-lamp')?'안쪽 탁자에서 새 별등을 놓아 보세요':ROOM_HINTS.home;
 if(!progress.ownedItemIds.includes('star-lamp')){
  if(roomId==='classroom')return '교실 한 개, 마을 두 개. 별을 찾아요';
  if(roomId==='courtyard')return '마을 산책길에서 별 두 개를 찾아요';
 }
 return ROOM_HINTS[roomId]??'지도를 열어 다음 장소를 골라요';
}
